import { LightningElement, api } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import getReview from '@salesforce/apex/RlyReviewController.getReview';
import approve from '@salesforce/apex/RlyReviewController.approve';
import reject from '@salesforce/apex/RlyReviewController.reject';
import bypassScan from '@salesforce/apex/RlyReviewController.bypassScan';
import rerunChecks from '@salesforce/apex/RlyReviewController.rerunChecks';
import refreshRequest from '@salesforce/apex/RlyReleaseController.refreshRequest';
import startPipeline from '@salesforce/apex/RlyReleaseController.startPipeline';
import getFilePair from '@salesforce/apex/RlyReviewController.getFilePair';
import saveFile from '@salesforce/apex/RlyReviewController.saveFile';
import syncBack from '@salesforce/apex/RlyReviewController.syncBack';
import { buildDiff } from 'c/rlyDiff';

const MAX_DIFF_LINES = 3000;

function errorText(e) {
    if (e && e.body) {
        return e.body.message || (e.body.pageErrors && e.body.pageErrors[0] && e.body.pageErrors[0].message) || 'Something went wrong.';
    }
    return e && e.message ? e.message : 'Something went wrong.';
}

function parseJson(text) {
    if (!text) {
        return null;
    }
    try {
        return JSON.parse(text);
    } catch (e) {
        return null;
    }
}

/** Unified diff (provider patch) to rows with old and new line numbers. */
function patchRows(patch) {
    const rows = [];
    let oldNo = 0;
    let newNo = 0;
    const lines = (patch || '').split('\n');
    for (let i = 0; i < lines.length && rows.length < MAX_DIFF_LINES; i++) {
        const line = lines[i];
        const hunk = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@(.*)$/.exec(line);
        if (hunk) {
            oldNo = Number(hunk[1]);
            newNo = Number(hunk[2]);
            rows.push({ id: 'h' + i, oldNo: '', newNo: '', sign: '', text: line, cls: 'rr-dl rr-dl-hunk' });
        } else if (line.startsWith('+')) {
            rows.push({ id: 'l' + i, oldNo: '', newNo: newNo++, sign: '+', text: line.slice(1), cls: 'rr-dl rr-dl-add' });
        } else if (line.startsWith('-')) {
            rows.push({ id: 'l' + i, oldNo: oldNo++, newNo: '', sign: '−', text: line.slice(1), cls: 'rr-dl rr-dl-del' });
        } else if (line.startsWith('\\')) {
            rows.push({ id: 'l' + i, oldNo: '', newNo: '', sign: '', text: line, cls: 'rr-dl rr-dl-note' });
        } else {
            rows.push({ id: 'l' + i, oldNo: oldNo++, newNo: newNo++, sign: '', text: line.slice(1), cls: 'rr-dl' });
        }
    }
    return rows;
}

const STAGE_LABELS = ['Raised', 'Pull request', 'Code scan', 'Validation', 'Approval', 'Merge', 'Deploy'];
// While a release is in one of these, the page asks for fresh status every POLL_MS.
const MOVING = ['Submitted', 'Workflow running', 'PR open', 'Approved', 'Merging', 'Deploying'];
const POLL_MS = 15000;

export default class OrgToGitRequestReview extends LightningElement {
    @api recordId;
    @api showBack = false;

    review;
    loading = false;
    error;
    tab = 'files';
    selectedFile;
    action; // approve, reject, bypass
    comment = '';
    actionError;
    pairs = {};       // filename -> rows, for files compared here
    pairLoading = false;
    pairError;
    editing = false;
    editLoading = false;
    editText = '';
    editMessage = '';
    editError;
    saving = false;
    fillEditor = false;

    connectedCallback() {
        this.load(true);
    }

    disconnectedCallback() {
        clearTimeout(this.pollTimer);
    }

    /** Starts a pipeline run the last action left pending, then reloads. */
    kick(id, withFiles) {
        return startPipeline({ requestId: id || this.recordId })
            .catch((e) => {
                this.error = errorText(e);
            })
            .then(() => this.load(withFiles));
    }

    // Keeps the page current on its own: no Refresh needed while the pipeline is working.
    schedulePoll() {
        clearTimeout(this.pollTimer);
        if (!MOVING.includes(this.req.Status__c)) {
            return;
        }
        this.pollTimer = setTimeout(() => {
            if (document.hidden || this.editing || this.action) {
                this.schedulePoll();
                return;
            }
            const before = this.req.Status__c;
            refreshRequest({ requestId: this.recordId })
                .then((r) => {
                    if (r && r.Status__c !== before) {
                        this.changed();
                        this.load(r.PR_Number__c && !(this.review && this.review.files && this.review.files.length));
                    } else {
                        this.schedulePoll();
                    }
                })
                .catch(() => this.schedulePoll());
        }, POLL_MS);
    }

    renderedCallback() {
        // A textarea's value has to be set as a property, after it renders.
        if (this.fillEditor) {
            const area = this.template.querySelector('textarea');
            if (area) {
                area.value = this.editText;
                this.fillEditor = false;
            }
        }
    }

    load(withFiles) {
        if (!this.recordId) {
            return;
        }
        this.loading = true;
        this.error = undefined;
        getReview({ requestId: this.recordId, includeFiles: withFiles })
            .then((r) => {
                const files = withFiles ? r.files : (this.review ? this.review.files : r.files);
                this.review = { ...r, files };
                if (!this.selectedFile && files && files.length) {
                    this.selectedFile = files[0].filename;
                    this.loadPair();
                }
                if (r.request.Pending_Run__c && !this.kicked) {
                    // The page that took the last action closed before starting the run: start it now.
                    this.kicked = true;
                    this.kick(this.recordId, withFiles);
                    return;
                }
                this.schedulePoll();
            })
            .catch((e) => {
                this.error = errorText(e);
            })
            .finally(() => {
                this.loading = false;
            });
    }

    // ---------- header ----------

    get req() { return this.review ? this.review.request : {}; }
    get ready() { return !!this.review; }
    get statusClass() {
        const s = this.req.Status__c;
        const tone = ['Deployed', 'Merged'].includes(s) ? 'ok'
            : ['Failed', 'Checks failed', 'Deploy failed', 'Rejected', 'Closed'].includes(s) ? 'bad'
            : s === 'Ready for approval' ? 'ready' : 'busy';
        return 'rr-pill rr-pill-' + tone;
    }
    get route() {
        const r = this.req;
        return (r.Org_Label__c || '') + ': ' + r.Source_Branch__c + ' → ' + r.Target_Branch__c;
    }
    get raisedBy() { return this.req.CreatedBy ? this.req.CreatedBy.Name : ''; }
    get changeName() {
        const label = (this.review && this.review.changeLabel) || 'pull request';
        return label.charAt(0).toUpperCase() + label.slice(1);
    }
    get prLabel() { return this.req.PR_Number__c ? this.changeName + ' #' + this.req.PR_Number__c : ''; }

    // ---------- pipeline ----------

    get stages() {
        const r = this.req;
        const st = r.Status__c;
        const state = (done, failed, current, skipped) =>
            (failed ? 'bad' : done ? 'ok' : skipped ? 'skip' : current ? 'cur' : 'todo');
        const prOpen = !!r.PR_Number__c;
        const scan = r.Scan_Status__c;
        const val = r.Validation_Status__c;
        const merged = ['Merged', 'Deploying', 'Deployed', 'Deploy failed'].includes(st);
        const stopped = st === 'Failed' || st === 'Closed';
        const states = [
            state(true, false, false, false),
            state(prOpen, st === 'Failed' && !prOpen, st === 'Workflow running' || st === 'Submitted', false),
            state(['Passed', 'Skipped', 'Bypassed'].includes(scan), ['Failed', 'Error'].includes(scan), scan === 'Pending' && !stopped, scan === 'Not configured'),
            state(['Passed', 'Skipped'].includes(val), ['Failed', 'Error'].includes(val), val === 'Pending' && !stopped, val === 'Not configured'),
            state(r.Approval_Status__c === 'Approved', r.Approval_Status__c === 'Rejected', st === 'Ready for approval', false),
            state(merged, st === 'Failed' && r.Approval_Status__c === 'Approved', st === 'Merging' || st === 'Approved', st === 'Closed'),
            state(st === 'Deployed', st === 'Deploy failed', st === 'Deploying', r.Deploy_Status__c === 'Not configured')
        ];
        const notes = [
            this.raisedBy,
            prOpen ? '#' + r.PR_Number__c : st === 'Failed' ? 'Failed' : 'Opening',
            scan === 'Bypassed' ? 'Bypassed' : scan === 'Not configured' ? 'Off' : stopped && scan === 'Pending' ? 'Not run' : scan || '',
            val === 'Not configured' ? 'Git only' : stopped && val === 'Pending' ? 'Not run' : val || '',
            r.Approval_Status__c || '',
            merged ? 'Merged' : st === 'Merging' ? 'Merging' : '',
            r.Deploy_Status__c === 'Not configured' ? 'Git only' : (st === 'Deployed' ? 'Deployed' : st === 'Deploying' ? 'Deploying' : st === 'Deploy failed' ? 'Failed' : '')
        ];
        const labels = [...STAGE_LABELS];
        labels[1] = this.changeName;
        const keep = labels.map((l, i) => i);
        return keep.map((i, n) => ({
            id: 's' + i,
            label: labels[i],
            note: notes[i],
            cls: 'rr-step rr-step-' + states[i] + (n === 0 ? ' rr-step-first' : ''),
            title: labels[i] + (notes[i] ? ': ' + notes[i] : ''),
            icon: states[i] === 'ok' ? '✓' : states[i] === 'bad' ? '✕' : states[i] === 'skip' ? '–' : String(n + 1)
        }));
    }

    // ---------- what failed ----------

    get failure() {
        const r = this.req;
        const st = r.Status__c;
        if (!['Checks failed', 'Failed', 'Deploy failed'].includes(st)) {
            return null;
        }
        const target = r.Target_Branch__c;
        const fix = this.review && this.review.canEdit
            ? 'Fix it in Files (Edit, then Save to branch) or in your org and raise again. Saving re-runs the checks.'
            : 'Fix the branch, then Re-run checks.';
        let f;
        if (st === 'Deploy failed') {
            const d = this.deployment;
            f = { title: 'Deployment to ' + target + ' failed', summary: d.text, tab: 'checks', runUrl: d.runUrl || r.Run_URL__c,
                lines: this.problemLines(d), next: 'The change is merged but not in ' + target + '. Fix the problem in a new release, or deploy again from the workflow.' };
        } else if (st === 'Failed') {
            f = { title: 'The workflow failed', summary: r.Error_Message__c || 'The pipeline stopped before the checks ran.', tab: 'checks',
                runUrl: r.Run_URL__c, lines: [], next: 'Open the run log for the step that failed. Fix the setup or the branch, then raise the release again.' };
        } else if (['Failed', 'Error'].includes(r.Validation_Status__c)) {
            const v = this.validation;
            const lines = this.problemLines(v);
            f = { title: 'Validation against ' + target + ' failed', tab: 'checks', runUrl: v.runUrl || r.Run_URL__c, lines,
                summary: (v.hasComponentErrors ? v.componentErrors.length + ' component error(s). ' : '')
                    + (v.hasTestFailures ? v.testFailures.length + ' test failure(s). ' : '') + (lines.length ? '' : v.text),
                next: fix };
        } else if (['Failed', 'Error'].includes(r.Scan_Status__c)) {
            const blocking = this.violations.filter((x) => ['Critical', 'High'].includes(x.sev));
            const list = blocking.length ? blocking : this.violations;
            f = { title: r.Scan_Status__c === 'Error' ? 'The code scan could not run' : 'Code scan found blocking problems', tab: 'scan',
                runUrl: this.scanRunUrl || r.Run_URL__c, summary: this.scanSummary,
                lines: list.map((x) => ({ id: x.id, where: x.where + ' · ' + x.rule, text: x.message })),
                next: fix + (this.canBypass ? ' If it is a false positive, an admin can Bypass scan.' : '') };
        } else {
            f = { title: 'A check failed', summary: r.Error_Message__c || '', tab: 'checks', runUrl: r.Run_URL__c, lines: [], next: fix };
        }
        const all = f.lines || [];
        f.lines = all.slice(0, 6);
        f.hasLines = f.lines.length > 0;
        f.more = all.length > 6 ? 'and ' + (all.length - 6) + ' more. See details.' : null;
        return f;
    }

    problemLines(check) {
        const lines = check.componentErrors.map((c) => ({
            id: c.id, where: (c.type ? c.type + ': ' : '') + (c.name || '') + (c.line ? ' line ' + c.line : ''), text: c.problem
        }));
        return lines.concat(check.testFailures.map((t) => ({ id: t.id, where: t.name + '.' + t.method, text: t.message })));
    }

    handleGoTab(event) {
        this.tab = event.currentTarget.dataset.tab;
    }

    // ---------- edit a file on the branch ----------

    get canEdit() { return this.review && this.review.canEdit; }
    get canEditFile() {
        const f = this.currentFile;
        return this.canEdit && !this.editing && f && f.status !== 'removed';
    }
    startEdit() {
        const f = this.currentFile;
        if (!f) {
            return;
        }
        this.editing = true;
        this.editLoading = true;
        this.editError = undefined;
        this.editMessage = '';
        getFilePair({ requestId: this.recordId, path: f.filename, baseRef: null, headRef: this.req.Source_Branch__c })
            .then((pair) => {
                this.editText = pair.new || '';
                this.fillEditor = true;
            })
            .catch((e) => {
                this.editError = errorText(e);
                this.editText = '';
            })
            .finally(() => {
                this.editLoading = false;
            });
    }
    handleEditText(event) { this.editText = event.target.value; }
    handleEditMessage(event) { this.editMessage = event.target.value; }
    handleEditKey(event) {
        if (event.key === 'Tab' && !event.shiftKey) {
            event.preventDefault();
            const el = event.target;
            const start = el.selectionStart;
            const end = el.selectionEnd;
            el.value = el.value.slice(0, start) + '    ' + el.value.slice(end);
            el.selectionStart = el.selectionEnd = start + 4;
            this.editText = el.value;
        }
    }
    cancelEdit() {
        this.editing = false;
        this.editError = undefined;
    }
    saveEdit() {
        const f = this.currentFile;
        if (!f) {
            return;
        }
        const el = this.template.querySelector('textarea');
        const content = el ? el.value : this.editText;
        this.saving = true;
        this.editError = undefined;
        saveFile({ requestId: this.recordId, path: f.filename, content, message: this.editMessage })
            .then(() => {
                this.editing = false;
                this.pairs = {};
                this.toast('Saved to ' + this.req.Source_Branch__c + '. The checks are running again.', 'success');
                this.changed();
                this.kick(this.recordId, true);
            })
            .catch((e) => {
                this.editError = errorText(e);
            })
            .finally(() => {
                this.saving = false;
            });
    }

    // ---------- sync back ----------

    get canSyncBack() { return this.review && this.review.canSyncBack; }
    get syncBackLabel() { return String((this.review && this.review.syncBackTarget) || '').toUpperCase(); }
    get syncBackHelp() {
        return 'Opens a ' + this.changeName.toLowerCase() + ' from ' + this.req.Target_Branch__c + ' into ' + this.syncBackLabel
            + ', validated against that org, so both orgs match after approval.';
    }
    handleSyncBack() {
        this.loading = true;
        syncBack({ requestId: this.recordId })
            .then((syncId) => startPipeline({ requestId: syncId }).catch(() => null))
            .then(() => {
                this.toast('Sync back to ' + this.syncBackLabel + ' raised. It appears in the release list.', 'success');
                this.changed();
                this.load(false);
            })
            .catch((e) => {
                this.error = errorText(e);
                this.loading = false;
            });
    }

    // ---------- actions ----------

    get canApprove() { return this.review && this.review.canApprove; }
    get canReject() { return this.review && this.review.canReject; }
    get canBypass() { return this.review && this.review.canBypass; }
    get canRerun() { return this.review && this.review.canRerun; }
    get blockedReason() {
        const r = this.review;
        if (!r || r.canApprove) {
            return null;
        }
        return this.req.Status__c === 'Ready for approval' ? r.approveBlockedReason : this.waitingText;
    }
    get waitingText() {
        const st = this.req.Status__c;
        const map = {
            'Submitted': 'Starting the workflow.',
            'Workflow running': 'The pipeline is opening the ' + this.changeName.toLowerCase() + '.',
            'Retrieving': 'Retrieving the components from this org.',
            'Validating': 'Validating against ' + this.req.Target_Branch__c + ' (check-only deployment).',
            'PR open': 'Waiting for the code scan and validation.',
            'Checks failed': 'A check failed. Fix the branch and Re-run checks, or an admin can bypass a failed scan.',
            'Rejected': 'Rejected. Fix the branch, then Re-run checks to ask for approval again.',
            'Approved': 'Approved. Starting the merge.',
            'Merging': 'Merging the ' + this.changeName.toLowerCase() + '.',
            'Deploying': 'Deploying to ' + this.req.Target_Branch__c + '.',
            'Deployed': 'Merged and deployed.',
            'Merged': 'Merged.',
            'Deploy failed': 'Merged, but the deployment failed. See Validation and deployment.',
            'Failed': this.req.Error_Message__c || 'The workflow failed.',
            'Closed': 'The ' + this.changeName.toLowerCase() + ' was closed outside Release Relay.'
        };
        return map[st] || '';
    }
    get showActionPanel() { return !!this.action; }
    get actionTitle() {
        return this.action === 'approve' ? this.approveLabel
            : this.action === 'reject' ? 'Reject' : 'Bypass the failed scan';
    }
    get actionHelp() {
        if (this.action === 'approve') {
            return 'Merges ' + this.changeName.toLowerCase() + ' #' + this.req.PR_Number__c + ' into ' + this.req.Target_Branch__c
                + (this.req.Target_Environment__c ? ' and deploys it to that org.' : '. Nothing is deployed for this target.');
        }
        return this.action === 'reject'
            ? 'Tell the developer what to change. They fix the branch and re-run the checks.'
            : 'The reason is saved on the release with your name. Use this for false positives, not to skip real problems.';
    }
    get commentLabel() {
        return this.action === 'approve' ? 'Comment (optional)' : this.action === 'reject' ? 'What needs to change' : 'Reason';
    }
    get confirmLabel() {
        return this.action === 'approve' ? this.approveLabel : this.action === 'reject' ? 'Reject' : 'Bypass scan';
    }
    get approveLabel() { return 'Approve and merge'; }
    get confirmVariant() { return this.action === 'reject' ? 'destructive' : 'brand'; }

    openApprove() { this.openAction('approve'); }
    openReject() { this.openAction('reject'); }
    openBypass() { this.openAction('bypass'); }
    openAction(name) {
        this.action = name;
        this.comment = '';
        this.actionError = undefined;
    }
    cancelAction() { this.action = undefined; }
    handleComment(event) { this.comment = event.target.value; }

    confirmAction() {
        const id = this.recordId;
        const call = this.action === 'approve' ? approve({ requestId: id, comment: this.comment })
            : this.action === 'reject' ? reject({ requestId: id, comment: this.comment })
            : bypassScan({ requestId: id, reason: this.comment });
        const done = this.action === 'approve' ? 'Approved. The ' + this.changeName.toLowerCase() + ' is being merged.'
            : this.action === 'reject' ? 'Rejected. The developer can see your comment.' : 'Scan bypassed.';
        this.loading = true;
        this.actionError = undefined;
        const approving = this.action === 'approve';
        call.then(() => {
            this.action = undefined;
            this.toast(done, 'success');
            this.changed();
            return approving ? this.kick(id, false) : this.load(false);
        }).catch((e) => {
            this.actionError = errorText(e);
            this.loading = false;
        });
    }

    handleRerun() {
        this.loading = true;
        rerunChecks({ requestId: this.recordId })
            .then(() => {
                this.toast('Checks started again. Results appear here as they finish.', 'success');
                this.changed();
                return this.kick(this.recordId, true);
            })
            .catch((e) => {
                this.error = errorText(e);
                this.loading = false;
            });
    }

    handleRefresh() {
        this.loading = true;
        refreshRequest({ requestId: this.recordId })
            .then(() => {
                this.changed();
                this.load(true);
            })
            .catch((e) => {
                this.error = errorText(e);
                this.loading = false;
            });
    }

    handleBack() {
        this.dispatchEvent(new CustomEvent('close'));
    }

    changed() {
        this.dispatchEvent(new CustomEvent('changed'));
    }

    toast(message, variant) {
        this.dispatchEvent(new ShowToastEvent({ title: this.req.Name, message, variant }));
    }

    // ---------- tabs ----------

    get tabs() {
        const scan = this.scan;
        const list = [
            { id: 'files', label: 'Files' + (this.fileCount ? ' (' + this.fileCount + ')' : '') },
            { id: 'scan', label: 'Code scan' + (scan && scan.total ? ' (' + scan.total + ')' : '') },
            { id: 'checks', label: 'Validation and deployment' },
            { id: 'items', label: 'Components' + (this.items.length ? ' (' + this.items.length + ')' : '') },
            { id: 'approval', label: 'Approval' }
        ];
        return list.map((t) => ({ ...t, cls: 'rr-tab' + (t.id === this.tab ? ' rr-tab-on' : ''), selected: t.id === this.tab ? 'true' : 'false' }));
    }
    handleTab(event) { this.tab = event.currentTarget.dataset.id; }
    get isFiles() { return this.tab === 'files'; }
    get isScan() { return this.tab === 'scan'; }
    get isChecks() { return this.tab === 'checks'; }
    get isItems() { return this.tab === 'items'; }
    get isApproval() { return this.tab === 'approval'; }

    // files
    get files() { return (this.review && this.review.files) || []; }
    get fileCount() { return this.files.length; }
    get filesError() { return this.review ? this.review.filesError : null; }
    get noFiles() { return this.review && !this.files.length && !this.filesError; }
    get fileRows() {
        return this.files.map((f) => {
            const parts = f.filename.split('/');
            return {
                id: f.filename,
                name: parts[parts.length - 1],
                folder: parts.slice(-3, -1).join('/'),
                status: f.status,
                adds: '+' + f.additions,
                dels: '−' + f.deletions,
                cls: 'rr-file' + (f.filename === this.selectedFile ? ' rr-file-on' : '') + ' rr-file-' + f.status
            };
        });
    }
    handleFile(event) {
        this.selectedFile = event.currentTarget.dataset.id;
        this.editing = false;
        this.loadPair();
    }
    get currentFile() { return this.files.find((f) => f.filename === this.selectedFile); }
    get diffRows() {
        const f = this.currentFile;
        if (!f) {
            return [];
        }
        return f.patch ? patchRows(f.patch) : (this.pairs[f.filename] || []);
    }
    get noPatch() {
        const f = this.currentFile;
        return f && !f.patch && !this.pairs[f.filename] && !this.pairLoading;
    }
    get noPatchText() {
        const f = this.currentFile;
        if (f && f.status === 'removed') {
            return 'This component is deleted by the release.';
        }
        return this.pairError || 'No text diff for this file (binary, or too large). Open the ' + this.changeName.toLowerCase() + ' to see it.';
    }

    /** Providers without patches (Azure DevOps, org to org): fetch both versions and compare here. */
    loadPair() {
        const f = this.currentFile;
        if (!f || f.patch || this.pairs[f.filename] || f.status === 'removed' || (!f.baseRef && !f.headRef)) {
            return;
        }
        this.pairLoading = true;
        this.pairError = undefined;
        getFilePair({ requestId: this.recordId, path: f.filename, baseRef: f.baseRef, headRef: f.headRef })
            .then((pair) => {
                const oldText = pair.old || '';
                const newText = pair.new || '';
                if (!oldText && !newText) {
                    this.pairError = 'Neither version could be read.';
                    return;
                }
                const d = buildDiff(oldText, newText);
                const rows = d.lines.map((l, i) => ({
                    id: 'p' + i, oldNo: '', newNo: '', sign: l.sign === '-' ? '−' : l.sign.trim(), text: l.text,
                    cls: l.cls.includes('add') ? 'rr-dl rr-dl-add' : l.cls.includes('del') ? 'rr-dl rr-dl-del' : l.cls.includes('gap') ? 'rr-dl rr-dl-hunk' : 'rr-dl'
                }));
                this.pairs = { ...this.pairs, [f.filename]: rows };
            })
            .catch((e) => {
                this.pairError = errorText(e);
            })
            .finally(() => {
                this.pairLoading = false;
            });
    }
    get patchTruncated() { return this.currentFile && this.currentFile.truncated; }

    // scan
    get scan() { return parseJson(this.req.Scan_Result__c); }
    get scanSummary() {
        const s = this.scan;
        const status = this.req.Scan_Status__c;
        if (!s) {
            return status === 'Pending' ? 'The scan is running.' : 'No scan result yet.';
        }
        if (status === 'Skipped') {
            return s.message || 'No code files to scan.';
        }
        return s.total + ' violation(s) in ' + (s.files || []).length + ' file(s). ' + (s.blocking || 0) + ' at '
            + (s.thresholdLabel || 'High') + ' or above, which blocks approval. Rules: ' + (s.rules || 'Recommended') + '.';
    }
    get scanCounts() {
        const c = (this.scan && this.scan.counts) || {};
        return ['Critical', 'High', 'Moderate', 'Low', 'Info'].map((k) => ({
            id: k, label: k, count: c[k] || 0, cls: 'rr-count rr-count-' + k.toLowerCase()
        }));
    }
    get violations() {
        const v = (this.scan && this.scan.violations) || [];
        return v.map((x, i) => ({
            id: 'v' + i,
            sev: x.severityLabel,
            sevCls: 'rr-sev rr-sev-' + String(x.severityLabel || '').toLowerCase(),
            rule: x.rule,
            engine: x.engine,
            where: (x.file || '').split('/').pop() + (x.line ? ':' + x.line : ''),
            path: x.file,
            message: x.message,
            url: x.url
        }));
    }
    get hasViolations() { return this.violations.length > 0; }
    get scanBypassed() { return this.req.Scan_Status__c === 'Bypassed'; }
    get bypassedBy() { return this.req.Scan_Bypassed_By__r ? this.req.Scan_Bypassed_By__r.Name : ''; }
    get scanRunUrl() { return this.scan ? this.scan.runUrl : null; }

    // validation and deployment
    get validation() { return this.checkView(parseJson(this.req.Validation_Result__c), this.req.Validation_Status__c, 'Validation'); }
    get deployment() { return this.checkView(parseJson(this.req.Deploy_Result__c), this.req.Deploy_Status__c, 'Deployment'); }
    checkView(r, status, label) {
        const notConfigured = status === 'Not configured';
        return {
            label,
            status: status || '—',
            pillCls: 'rr-pill rr-pill-' + (['Passed', 'Deployed', 'Skipped'].includes(status) ? 'ok'
                : ['Failed', 'Error'].includes(status) ? 'bad' : notConfigured ? 'muted' : 'busy'),
            text: notConfigured ? 'Not set up for ' + this.req.Target_Branch__c + ': this target is Git only.'
                : !r ? (status === 'Pending' || status === 'Deploying' ? 'Running.' : 'No result yet.')
                : (r.message || (r.testsRun ? r.testsRun + ' test(s) ran, ' + (r.testLevel || '') : 'No problems.')),
            runUrl: r ? r.runUrl : null,
            componentErrors: ((r && r.componentErrors) || []).map((c, i) => ({ id: label + 'c' + i, ...c })),
            testFailures: ((r && r.testFailures) || []).map((t, i) => ({ id: label + 't' + i, ...t })),
            hasComponentErrors: !!(r && r.componentErrors && r.componentErrors.length),
            hasTestFailures: !!(r && r.testFailures && r.testFailures.length)
        };
    }

    // items
    get items() {
        return ((this.review && this.review.items) || []).map((i) => ({
            id: i.Id, type: i.Metadata_Type__c, name: i.Component_Name__c, change: i.Change_Type__c,
            cls: 'rr-chg rr-chg-' + String(i.Change_Type__c || '').toLowerCase()
        }));
    }
    get noItems() { return this.items.length === 0; }

    // approval
    get approver() { return this.req.Approved_By__r ? this.req.Approved_By__r.Name : ''; }
    get hasApproval() { return !!this.req.Approval_Status__c && this.req.Approval_Status__c !== 'Pending'; }
}
